function scr_caterpillar_interpolate()
{
    remx[0] = obj_mainchara.x;
    remy[0] = obj_mainchara.y;
    facing[0] = global.facing;
    for (i = target; i > 0; i -= 1)
    {
        facing[i] = 2;
        remx[i] = obj_mainchara.x + ((x - obj_mainchara.x) * (i / target));
        remy[i] = obj_mainchara.y + ((y - obj_mainchara.y) * (i / target));
    }
}

function scr_unmarkify_caterpillar()
{
    for (i = 0; i < 2; i += 1)
    {
        if (instance_exists(global.cinstance[i]))
        {
            if (global.char[i + 1] == 2)
            {
                if (global.cinstance[i].x != s.x || global.cinstance[i].y != s.x)
                {
                    global.cinstance[i].x = s.x;
                    global.cinstance[i].y = s.y + 10;
                    with (global.cinstance[i])
                    {
                        scr_caterpillar_interpolate();
                    }
                    global.cinstance[i].y -= 10;
                }
                with (global.cinstance[i])
                {
                    if (global.facing == 0)
                    {
                        sprite_index = dsprite;
                    }
                    if (global.facing == 1)
                    {
                        sprite_index = rsprite;
                    }
                    if (global.facing == 2)
                    {
                        sprite_index = usprite;
                    }
                    if (global.facing == 3)
                    {
                        sprite_index = lsprite;
                    }
                    visible = 1;
                }
                with (s)
                {
                    instance_destroy();
                }
            }
            if (global.char[i + 1] == 3)
            {
                if (global.cinstance[i].x != r.x || global.cinstance[i].y != r.x)
                {
                    global.cinstance[i].x = r.x;
                    global.cinstance[i].y = r.y + 10;
                    with (global.cinstance[i])
                    {
                        scr_caterpillar_interpolate();
                    }
                    global.cinstance[i].y -= 10;
                }
                with (global.cinstance[i])
                {
                    if (global.facing == 0)
                    {
                        sprite_index = dsprite;
                    }
                    if (global.facing == 1)
                    {
                        sprite_index = rsprite;
                    }
                    if (global.facing == 2)
                    {
                        sprite_index = usprite;
                    }
                    if (global.facing == 3)
                    {
                        sprite_index = lsprite;
                    }
                    visible = 1;
                }
                with (r)
                {
                    instance_destroy();
                }
            }
        }
    }
}

